import{_ as o,o as t,c as d,a5 as s}from"./chunks/framework.B1nibuwM.js";const m=JSON.parse('{"title":"Documentation toolchain","description":"","frontmatter":{},"headers":[],"relativePath":"dev/docs-toolchain.md","filePath":"dev/docs-toolchain.md"}'),a={name:"dev/docs-toolchain.md"};function n(r,e,c,i,h,l){return t(),d("div",null,[...e[0]||(e[0]=[s('<h1 id="documentation-toolchain" tabindex="-1">Documentation toolchain <a class="header-anchor" href="#documentation-toolchain" aria-label="Permalink to &quot;Documentation toolchain&quot;">​</a></h1><p>How the documentation under <code>docs/</code> is produced, and which parts of it you may edit by hand.</p><p>This covers the <em>documentation</em> toolchain only. For the general development loop — lint, static analysis, tests, and what to run before a pull request — see <a href="https://github.com/zircote/swagger-php/blob/master/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a>.</p><h2 id="generated-pages-—-do-not-edit" tabindex="-1">Generated pages — do not edit <a class="header-anchor" href="#generated-pages-—-do-not-edit" aria-label="Permalink to &quot;Generated pages — do not edit&quot;">​</a></h2><p>These pages are written by <code>composer docs:gen</code>. Editing them directly is wasted work: the next <code>docs:gen</code> overwrites your changes, and so does <code>composer docs:build</code>, which runs <code>docs:gen</code> first.</p><table tabindex="0"><thead><tr><th>Page</th><th>Built from</th></tr></thead><tbody><tr><td><code>reference/annotations.md</code></td><td><code>src/Annotations/</code> docblocks + <code>snippets/preamble_annotations.md</code></td></tr><tr><td><code>reference/attributes.md</code></td><td><code>src/Attributes/</code> docblocks + <code>snippets/preamble_attributes.md</code></td></tr><tr><td><code>reference/spec-attributes.md</code></td><td><code>src/Spec/</code> docblocks + <code>snippets/preamble_spec-attributes.md</code></td></tr><tr><td><code>reference/processors.md</code></td><td><code>src/Processors/</code> docblocks + <code>snippets/preamble_processors.md</code> + prose in <code>ProcessorGenerator</code></td></tr><tr><td><code>reference/augmenters.md</code></td><td><code>src/Augmenter/</code> docblocks + <code>snippets/preamble_augmenters.md</code> + prose in <code>AugmenterGenerator</code></td></tr><tr><td><code>guide/examples.md</code></td><td>example sources + the per-example <code>docs/examples/specs/*/Readme.md</code></td></tr></tbody></table><p>To change one of these, change its source and re-run <code>composer docs:gen</code>.</p><p>Note that some prose lives <em>inside</em> the generators rather than in any markdown file — the <code>-c</code> and <code>-D</code> explanations in the &quot;Configuration&quot; sections are string literals in <code>tools/src/Docs/Reference/{Augmenter,Processor}Generator.php</code>.</p><p>Everything else under <code>docs/</code> is hand-written — including the top-level <code>docs/examples/Readme.md</code>, since only the per-example ones feed the generated page.</p><h2 id="docs-gen-is-a-drift-check" tabindex="-1"><code>docs:gen</code> is a drift check <a class="header-anchor" href="#docs-gen-is-a-drift-check" aria-label="Permalink to &quot;`docs:gen` is a drift check&quot;">​</a></h2><p>The generators are deterministic, and committed output is expected to match its source. So:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:gen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --porcelain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/</span></span></code></pre></div><p>Any output means the committed pages have drifted, and the regenerated version is the correct one. Worth running before opening a pull request.</p><p>Run it with an otherwise-clean tree, or scope the <code>git status</code> to the generated pages — <code>docs/reference/</code> holds hand-written ones too, so a directory-wide check reports your own edits as drift.</p><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Notes</th></tr></thead><tbody><tr><td><code>composer docs:gen</code></td><td>regenerate the pages listed above</td></tr><tr><td><code>composer docs:build</code></td><td>runs <code>docs:gen</code>, then builds the static site</td></tr><tr><td><code>composer docs:dev</code></td><td>local preview — <strong>long-running</strong>, prints its URL on startup and does not return</td></tr></tbody></table><h2 id="what-counts-as-a-documented-config-setting" tabindex="-1">What counts as a documented config setting <a class="header-anchor" href="#what-counts-as-a-documented-config-setting" aria-label="Permalink to &quot;What counts as a documented config setting&quot;">​</a></h2><p><code>reference/augmenters.md</code> and <code>reference/processors.md</code> list the options accepted by <code>-c name.option=value</code>. A setting qualifies when it is <strong>a constructor parameter that is not object typed</strong>:</p><ul><li>constructor parameters are the public configuration contract, by convention</li><li>object typed parameters — factories, resolvers, the generator — are collaborators, not settings, and cannot be expressed as a CLI value</li></ul><p>This is implemented once, in <code>DocGenerator::configurableParameters()</code>, and mirrors what <code>Utils\\Pipeline::getConfig()</code> reports at runtime. The two are aligned by hand rather than by construction; if you change one, check the other. The check is that <code>./bin/openapi --mode spec -D src</code> lists exactly the settings the reference page documents.</p><h2 id="cli-behavior-worth-knowing" tabindex="-1">CLI behavior worth knowing <a class="header-anchor" href="#cli-behavior-worth-knowing" aria-label="Permalink to &quot;CLI behavior worth knowing&quot;">​</a></h2><ul><li><code>-D</code> / <code>--defaults</code> prints the resolved default config, but still requires the <code>paths</code> argument: <code>./bin/openapi --mode spec -D src</code>, not <code>./bin/openapi --mode spec -D</code>.</li><li><code>--version</code> sets the target <strong>OpenAPI</strong> version, not the tool version.</li><li>Help output is standard Symfony Console format, from <code>./bin/openapi -h</code>.</li><li>Unknown <code>-c</code> keys are reported as warnings in <strong>spec</strong> mode, via <code>Pipeline::configure()</code>. In <strong>classic</strong> mode they are silently ignored, because configuration is routed through <code>Generator::setConfig()</code> instead. A typo in a classic <code>-c</code> key fails invisibly.</li></ul><h2 id="known-rough-edge" tabindex="-1">Known rough edge <a class="header-anchor" href="#known-rough-edge" aria-label="Permalink to &quot;Known rough edge&quot;">​</a></h2><p><code>AugmenterGenerator</code> and <code>ProcessorGenerator</code> share a lot of near-identical code — <code>collectOptions()</code>, <code>resolveDefault()</code>, and their CLI prose blocks. A fix to one usually needs applying to the other. They have also diverged: <code>AugmenterGenerator</code> renders through the <code>tools/src/Docs/Sections/</code> abstraction and emits markdown lists, while <code>ProcessorGenerator</code> renders inline and emits HTML <code>&lt;span&gt;</code> markup, which is why the two reference pages look different.</p>',24)])])}const u=o(a,[["render",n]]);export{m as __pageData,u as default};
